class Solution {
public:
    int search(vector<int>& a, int target) {
        int lo = 0, hi = (int)a.size() - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) return mid;
            if (a[lo] <= a[mid]) {                 // left half sorted
                if (a[lo] <= target && target < a[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {                               // right half sorted
                if (a[mid] < target && target <= a[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }
};

class Solution:
    def search(self, a: list[int], target: int) -> int:
        lo, hi = 0, len(a) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if a[mid] == target:
                return mid
            if a[lo] <= a[mid]:                    # left half sorted
                if a[lo] <= target < a[mid]:
                    hi = mid - 1
                else:
                    lo = mid + 1
            else:                                  # right half sorted
                if a[mid] < target <= a[hi]:
                    lo = mid + 1
                else:
                    hi = mid - 1
        return -1

class Solution {
public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int lo = 1, hi = *max_element(piles.begin(), piles.end());
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long long hours = 0;
            for (int x : piles) hours += (x + mid - 1) / mid;
            if (hours <= h) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

class Solution:
    def minEatingSpeed(self, piles: list[int], h: int) -> int:
        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            hours = sum((x + mid - 1) // mid for x in piles)
            if hours <= h:
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution {
public:
    double findMedianSortedArrays(vector<int>& A, vector<int>& B) {
        if (A.size() > B.size()) swap(A, B);
        int m = A.size(), n = B.size(), lo = 0, hi = m;
        const long long NEG = LLONG_MIN, POS = LLONG_MAX;
        while (lo <= hi) {
            int i = (lo + hi) / 2, j = (m + n + 1) / 2 - i;
            long long aL = i == 0 ? NEG : A[i-1], aR = i == m ? POS : A[i];
            long long bL = j == 0 ? NEG : B[j-1], bR = j == n ? POS : B[j];
            if (aL <= bR && bL <= aR) {
                if ((m + n) % 2) return max(aL, bL);
                return (max(aL, bL) + min(aR, bR)) / 2.0;
            } else if (aL > bR) hi = i - 1;
            else lo = i + 1;
        }
        return 0.0;
    }
};

class Solution:
    def findMedianSortedArrays(self, A: list[int], B: list[int]) -> float:
        if len(A) > len(B):
            A, B = B, A
        m, n = len(A), len(B)
        lo, hi = 0, m
        while lo <= hi:
            i = (lo + hi) // 2
            j = (m + n + 1) // 2 - i
            aL = float('-inf') if i == 0 else A[i-1]
            aR = float('inf') if i == m else A[i]
            bL = float('-inf') if j == 0 else B[j-1]
            bR = float('inf') if j == n else B[j]
            if aL <= bR and bL <= aR:
                if (m + n) % 2:
                    return max(aL, bL)
                return (max(aL, bL) + min(aR, bR)) / 2
            elif aL > bR:
                hi = i - 1
            else:
                lo = i + 1
        return 0.0
